  3281  /* kex_agree_instr
  3282   * Kex specific variant of strstr()
  3283   * Needle must be precede by BOL or ',', and followed by ',' or EOL
  3284   */
  3285  static unsigned char *
  3286  kex_agree_instr(unsigned char *haystack, unsigned long haystack_len,
  3287                  const unsigned char *needle, unsigned long needle_len)
  3288  {
  3289      unsigned char *s;
  3290
  3291      /* Haystack too short to bother trying */
  3292      if(haystack_len < needle_len) {
  3293          return NULL;
  3294      }
  3295
  3296      /* Needle at start of haystack */
  3297      if((strncmp((char *) haystack, (char *) needle, needle_len) == 0) &&
  3298          (needle_len == haystack_len || haystack[needle_len] == ',')) {
  3299          return haystack;
  3300      }
  3301
  3302      s = haystack;
  3303      /* Search until we run out of comas or we run out of haystack,
  3304         whichever comes first */
  3305      while((s = (unsigned char *) strchr((char *) s, ','))
  3306             && ((haystack_len - (s - haystack)) > needle_len)) {
  3307          s++;
  3308          /* Needle at X position */
  3309          if((strncmp((char *) s, (char *) needle, needle_len) == 0) &&
  3310              (((s - haystack) + needle_len) == haystack_len
  3311               || s[needle_len] == ',')) {
  3312              return s;
  3313          }
  3314      }
  3315
  3316      return NULL;
  3317  }
