  3339  /* kex_agree_hostkey
  3340   * Agree on a Hostkey which works with this kex
  3341   */
  3342  static int kex_agree_hostkey(LIBSSH2_SESSION * session,
  3343                               unsigned long kex_flags,
  3344                               unsigned char *hostkey, unsigned long hostkey_len)
  3345  {
  3346      const LIBSSH2_HOSTKEY_METHOD **hostkeyp = libssh2_hostkey_methods();
  3347      unsigned char *s;
  3348
  3349      if(session->hostkey_prefs) {
  3350          s = (unsigned char *) session->hostkey_prefs;
  3351
  3352          while(s && *s) {
  3353              unsigned char *p = (unsigned char *) strchr((char *) s, ',');
  3354              size_t method_len = (p ? (size_t)(p - s) : strlen((char *) s));
  3355              if(kex_agree_instr(hostkey, hostkey_len, s, method_len)) {
  3356                  const LIBSSH2_HOSTKEY_METHOD *method =
  3357                      (const LIBSSH2_HOSTKEY_METHOD *)
  3358                      kex_get_method_by_name((char *) s, method_len,
  3359                                             (const LIBSSH2_COMMON_METHOD **)
  3360                                             hostkeyp);
  3361
  3362                  if(!method) {
  3363                      /* Invalid method -- Should never be reached */
  3364                      return -1;
  3365                  }
  3366
  3367                  /* So far so good, but does it suit our purposes? (Encrypting
  3368                     vs Signing) */
  3369                  if(((kex_flags & LIBSSH2_KEX_METHOD_FLAG_REQ_ENC_HOSTKEY) ==
  3370                       0) || (method->encrypt)) {
  3371                      /* Either this hostkey can do encryption or this kex just
  3372                         doesn't require it */
  3373                      if(((kex_flags & LIBSSH2_KEX_METHOD_FLAG_REQ_SIGN_HOSTKEY)
  3374                           == 0) || (method->sig_verify)) {
  3375                          /* Either this hostkey can do signing or this kex just
  3376                             doesn't require it */
  3377                          session->hostkey = method;
  3378                          return 0;
  3379                      }
  3380                  }
  3381              }
  3382
  3383              s = p ? p + 1 : NULL;
  3384          }
  3385          return -1;
  3386      }
  3387
  3388      while(hostkeyp && (*hostkeyp) && (*hostkeyp)->name) {
  3389          s = kex_agree_instr(hostkey, hostkey_len,
  3390                              (unsigned char *) (*hostkeyp)->name,
  3391                              strlen((*hostkeyp)->name));
  3392          if(s) {
  3393              /* So far so good, but does it suit our purposes? (Encrypting vs
  3394                 Signing) */
  3395              if(((kex_flags & LIBSSH2_KEX_METHOD_FLAG_REQ_ENC_HOSTKEY) == 0) ||
  3396                  ((*hostkeyp)->encrypt)) {
  3397                  /* Either this hostkey can do encryption or this kex just
  3398                     doesn't require it */
  3399                  if(((kex_flags & LIBSSH2_KEX_METHOD_FLAG_REQ_SIGN_HOSTKEY) ==
  3400                       0) || ((*hostkeyp)->sig_verify)) {
  3401                      /* Either this hostkey can do signing or this kex just
  3402                         doesn't require it */
  3403                      session->hostkey = *hostkeyp;
  3404                      return 0;
  3405                  }
  3406              }
  3407          }
  3408          hostkeyp++;
  3409      }
  3410
  3411      return -1;
  3412  }
